import pandas as pd
import numpy as np

# Load the datasets with encoding parameter to handle special characters
def load_csv(file_path):
    try:
        return pd.read_csv(file_path, encoding='utf-8')
    except UnicodeDecodeError:
        return pd.read_csv(file_path, encoding='latin1')

df_interbank = load_csv('opensource/articles_and_reports/S2405918823000168/Data/Table_3500453149129901330.csv')
df_exchange = load_csv('opensource/articles_and_reports/S2405918823000168/Data/Table_-2624778818710448170.csv')

# Preprocess the datasets to clean and convert necessary columns
def clean_data(df):
    df.replace('nan', np.nan, inplace=True)
    df.fillna('', inplace=True)  # Fill NaN values with empty string to ease concatenation
    df.columns = df.columns.str.strip()  # Remove leading/trailing whitespace in column names
    return df

df_interbank = clean_data(df_interbank)
df_exchange = clean_data(df_exchange)

# Function to convert string to float while handling special characters
def safe_str_to_float(value):
    try:
        value = value.replace('\u2212', '-')  # Replace special negative sign with regular negative sign
        return float(value.replace('(', '').replace(')', ''))
    except ValueError:
        print(f"Conversion error for value: {value}")
        return np.nan

# Define a function to extract effect sizes and statistical significance
def extract_effects_significance(df, risk_factors):
    results = {}
    for factor in risk_factors:
        indices = df.index[df.iloc[:, 0] == factor].tolist()
        if len(indices) == 2:  # Assuming format as shown in preview
            effect_sizes_raw = df.iloc[indices[0], 1:].values
            significance_raw = df.iloc[indices[1], 1:].values

            effect_sizes = []
            significance = []

            for i in range(len(effect_sizes_raw)):
                effect_size_val = safe_str_to_float(effect_sizes_raw[i])
                significance_val = safe_str_to_float(significance_raw[i])
                if not np.isnan(effect_size_val):
                    effect_sizes.append(effect_size_val)
                    significance.append(significance_val)

            results[factor] = {'Effect Sizes': effect_sizes, 'Significance': significance}
    return results

# Define the credit risk and liquidity risk factors
risk_factors = ['Rating', 'Amihud']

# Obtain the results for both markets
results_interbank = extract_effects_significance(df_interbank, risk_factors)
results_exchange = extract_effects_significance(df_exchange, risk_factors)

# Print the results
print("Interbank Market\n")
for factor, values in results_interbank.items():
    print(f"Factor: {factor}")
    print(f"Effect Sizes: {values['Effect Sizes']}")
    print(f"Significance: {values['Significance']}\n")

print("Exchange Market\n")
for factor, values in results_exchange.items():
    print(f"Factor: {factor}")
    print(f"Effect Sizes: {values['Effect Sizes']}")
    print(f"Significance: {values['Significance']}\n")

