import pandas as pd
import re
from fractions import Fraction

# Load data
all_drinks_df = pd.read_csv('opensource/tidytuesday/2020-05-26/Data/all_drinks.csv')

# Function to convert measurement to oz
def convert_to_oz(measurement):
    try:
        if pd.isna(measurement):
            return 0

        # Handle fractions and mixed numbers
        measurement = measurement.replace('-', ' ')
        number_parts = measurement.split()
        number = sum(float(Fraction(part)) for part in number_parts if re.match(r'^\d', part))

        if 'oz' in measurement:
            return number
        elif 'ml' in measurement:
            return number * 0.033814
        elif 'cl' in measurement:
            return number * 0.33814
        elif 'tsp' in measurement:
            return number * 0.166667
        elif 'tbl' in measurement or 'tbsp' in measurement:
            return number * 0.5
        elif 'shot' in measurement:
            return number * 1.5
        else:
            return 0
    except:
        return 0

# Filter margarita recipes and ingredients with tequila
is_margarita = all_drinks_df['strDrink'].str.contains(r'\bMargarita\b', case=False, na=False)
margarita_df = all_drinks_df[is_margarita]

# List of columns containing the ingredient information in all_drinks_df
ingredient_columns = [col for col in all_drinks_df.columns if 'strIngredient' in col]
measure_columns = [col for col in all_drinks_df.columns if 'strMeasure' in col]

# Extract tequila measurements from margarita recipes
tequila_measures = []

for _, row in margarita_df.iterrows():
    for ingredient_col, measure_col in zip(ingredient_columns, measure_columns):
        if pd.notna(row[ingredient_col]) and 'tequila' in row[ingredient_col].lower():
            measurement = row[measure_col]
            amount = convert_to_oz(measurement)
            tequila_measures.append(amount)

# Calculate average amount of tequila used
if tequila_measures:
    average_tequila = sum(tequila_measures) / len(tequila_measures)
else:
    average_tequila = 0

print(f"The average amount of tequila used in the margarita recipes is: {average_tequila:.2f} oz")

import pandas as pd

# Load the dataset
file_path = 'opensource/tidytuesday/2020-05-19/Data/vb_matches.csv'
df = pd.read_csv(file_path)
df.columns = df.columns.str.strip()  # Remove any leading/trailing whitespace from column names

# Function to calculate hit percentage
def calculate_hit_percentage(kills, errors, attacks):
    if pd.notna(attacks) and attacks > 0:
        return (kills - errors) / attacks * 100
    else:
        return 0.0  # Return zero if no attacks or attacks is missing

# Find a player's statistics in the dataframe for a given match
def get_player_stats(player_name, match_num):
    match_df = df[df['match_num'] == match_num]

    if match_df.empty:
        return None, False  # Match number not found

    stats = {}
    player_found = False

    for index, row in match_df.iterrows():
        if row['w_player1'] == player_name:
            player_found = True
            stats = {
                "tot_attacks": row['w_p1_tot_attacks'],
                "tot_kills": row['w_p1_tot_kills'],
                "tot_errors": row['w_p1_tot_errors']
            }
        elif row['w_player2'] == player_name:
            player_found = True
            stats = {
                "tot_attacks": row['w_p2_tot_attacks'],
                "tot_kills": row['w_p2_tot_kills'],
                "tot_errors": row['w_p2_tot_errors']
            }
        elif row['l_player1'] == player_name:
            player_found = True
            stats = {
                "tot_attacks": row['l_p1_tot_attacks'],
                "tot_kills": row['l_p1_tot_kills'],
                "tot_errors": row['l_p1_tot_errors']
            }
        elif row['l_player2'] == player_name:
            player_found = True
            stats = {
                "tot_attacks": row['l_p2_tot_attacks'],
                "tot_kills": row['l_p2_tot_kills'],
                "tot_errors": row['l_p2_tot_errors']
            }

    # Handle cases with NaN values
    stats = {k: (0 if pd.isna(v) else v) for k, v in stats.items()}

    return stats if player_found else None, player_found

# Example usage
player_name = "Facundo Palavecino"  # Replace with the name of the player you want to query
match_num = 67  # Replace with the match number you want to query

player_stats, player_found = get_player_stats(player_name, match_num)

if player_found:
    hit_percentage = calculate_hit_percentage(player_stats['tot_kills'], player_stats['tot_errors'], player_stats['tot_attacks'])
    print(f"Hit percentage for {player_name} in match number {match_num} is {hit_percentage:.2f}%")
else:
    print(f"Player {player_name} not found in match number {match_num} or missing attack data")

import pandas as pd
from fractions import Fraction


# Load the datasets
all_drinks_df = pd.read_csv('opensource/tidytuesday/2020-05-26/Data/all_drinks.csv')
boston_cocktails_df = pd.read_csv('opensource/tidytuesday/2020-05-26/Data/boston_cocktails.csv')

# Function to convert measurements to ounces
def convert_to_oz(measure):
    if pd.isnull(measure):
        return 0
    measure = measure.strip().lower()
    try:
        if 'oz' in measure:
            return float(sum(Fraction(s) for s in measure.replace('oz', '').strip().split()))
        elif 'shot' in measure:
            return float(sum(Fraction(s) for s in measure.replace('shot', '').strip().split())) * 1.5  # Assuming a shot is 1.5 oz
        elif 'ml' in measure:
            return float(sum(Fraction(s) for s in measure.replace('ml', '').strip().split())) * 0.033814  # 1 ml is 0.033814 oz
        elif 'cl' in measure:
            return float(sum(Fraction(s) for s in measure.replace('cl', '').strip().split())) * 0.33814  # 1 cl is 0.33814 oz
        elif 'cup' in measure:
            return float(sum(Fraction(s) for s in measure.replace('cup', '').strip().split())) * 8  # Assuming 1 cup is 8 oz
        # Add more conversion rules if needed
        return float(sum(Fraction(s) for s in measure.split()))
    except (ValueError, ZeroDivisionError):
        return 0

# Extract relevant columns for analysis
tequila_ingredients = ['Tequila']
lime_ingredients = ['Lime Juice']

def get_tequila_and_lime_ratio_all_drinks(row):
    tequila_amount = 0
    lime_amount = 0

    for i in range(1, 16):
        if row[f'strIngredient{i}'] in tequila_ingredients:
            tequila_amount += convert_to_oz(row[f'strMeasure{i}'])
        elif row[f'strIngredient{i}'] in lime_ingredients:
            lime_amount += convert_to_oz(row[f'strMeasure{i}'])

    if lime_amount == 0:
        return None
    return tequila_amount / lime_amount

# Find margarita recipes
margarita_all_drinks = all_drinks_df[all_drinks_df['strDrink'].str.contains('Margarita', case=False, na=False)]
margarita_boston_cocktails = boston_cocktails_df[boston_cocktails_df['name'].str.contains('Margarita', case=False, na=False)]

# Compute the ratios for 'all_drinks'
ratios_all_drinks = margarita_all_drinks.apply(get_tequila_and_lime_ratio_all_drinks, axis=1)
ratios_all_drinks = ratios_all_drinks.dropna().tolist()

# Compute the ratios for 'boston_cocktails'
boston_ratios = []
for name, group in margarita_boston_cocktails.groupby('name'):
    tequila_amount = group[group['ingredient'].str.contains('Tequila', case=False)]['measure'].apply(convert_to_oz).sum()
    lime_amount = group[group['ingredient'].str.contains('Lime Juice', case=False)]['measure'].apply(convert_to_oz).sum()
    if lime_amount > 0:
        boston_ratios.append(tequila_amount / lime_amount)

# Combine both ratios list
combined_ratios = ratios_all_drinks + boston_ratios

# Calculate average ratio
average_ratio = sum(combined_ratios) / len(combined_ratios) if combined_ratios else 0

print(f"Average ratio of tequila to lime juice in margarita recipes: {average_ratio:.2f}")
